use std::future::Future;

pub trait Store: Send + Sync {
    fn load(&self, id: u32) -> impl Future<Output = Option<String>>;
}

async fn warm<S: Store + 'static>(store: S) {
    let handle = tokio::spawn(async move {
        store.load(1).await
    });
    let _ = handle.await;
}

