    let (number, seen) = store
        .update_seen(learner, |current| {
            let mut seen = current.unwrap_or_else(fresh);
            let number = seen.next_round();
            seen.end_round(number);
            Ok(Decision::Put(seen.clone(), (number, seen)))
        })
        .await?;
    round = number;
    bank = Some((store, seen));
}

class Store:
    def __init__(self):
        self.pending = {}
        self.graded = {}

    def create_if_absent(self, s):
        if s.key in self.pending:
            return False
        self.pending[s.key] = s
        return True

    def grade(self, key):
        self.graded[key] = self.pending.pop(key)

def open_session(store, s):
    if not store.create_if_absent(s):
        return None
    return s

/// Record that `id` was shown in round `round`. Only ever moves
/// forward: a round recorded late, after a later round showed `id`
/// too, leaves the later one, so that records of concurrent rounds can
/// be merged in any order.
pub fn show(&mut self, id: &BankId, round: u64) {
    let last = self.last_seen.entry(id.clone()).or_insert(round);
    *last = (*last).max(round);
    self.rounds = self.rounds.max(round);
}
